     1→//! Unit tests for protocol preference storage.
     2→//!
     3→//! Tests the storage and retrieval of user's preferred protocol (BLE vs ANT+)
     4→//! for dual-protocol sensors, including persistence and integration with
     5→//! the DualProtocolDetector.
     6→
     7→use rust_ride::sensors::types::{DiscoveredSensor, Protocol, SensorProtocol, SensorType};
     8→use rust_ride::sensors::dual_protocol::{
     9→    DualProtocolBinding, DualProtocolDetector, ProtocolPreference,
    10→    ProtocolPreferenceManager,
    11→};
    12→use std::path::PathBuf;
    13→use std::time::Instant;
    14→use tempfile::TempDir;
    15→
    16→// ============================================================================
    17→// Helper functions
    18→// ============================================================================
    19→
    20→/// Create a BLE discovered sensor for testing.
    21→fn make_ble_sensor(name: &str, sensor_type: SensorType) -> DiscoveredSensor {
    22→    let protocol = match sensor_type {
    23→        SensorType::Trainer | SensorType::SmartTrainer => Protocol::BleFtms,
    24→        SensorType::PowerMeter => Protocol::BleCyclingPower,
    25→        SensorType::HeartRate => Protocol::BleHeartRate,
    26→        _ => Protocol::BleCsc,
    27→    };
    28→
    29→    DiscoveredSensor {
    30→        device_id: format!("ble:{}", name.replace(' ', "_").to_lowercase()),
    31→        name: name.to_string(),
    32→        sensor_type,
    33→        protocol,
    34→        signal_strength: Some(-60),
    35→        last_seen: Instant::now(),
    36→    }
    37→}
    38→
    39→/// Create an ANT+ discovered sensor for testing.
    40→fn make_ant_sensor(name: &str, device_number: u16, sensor_type: SensorType) -> DiscoveredSensor {
    41→    let protocol = match sensor_type {
    42→        SensorType::HeartRate => Protocol::AntHeartRate,
    43→        SensorType::PowerMeter => Protocol::AntPower,
    44→        SensorType::Trainer | SensorType::SmartTrainer => Protocol::AntFec,
    45→        _ => Protocol::AntSpeedCadence,
    46→    };
    47→
    48→    DiscoveredSensor {
    49→        device_id: format!("ant+:{}:{}", device_type_number(sensor_type), device_number),
    50→        name: name.to_string(),
    51→        sensor_type,
    52→        protocol,
    53→        signal_strength: None,
    54→        last_seen: Instant::now(),
    55→    }
    56→}
    57→
    58→/// Get ANT+ device type number for sensor type.
    59→fn device_type_number(sensor_type: SensorType) -> u8 {
    60→    match sensor_type {
    61→        SensorType::HeartRate => 120,
    62→        SensorType::PowerMeter => 11,
    63→        SensorType::Trainer | SensorType::SmartTrainer => 17,
    64→        _ => 121,
    65→    }
    66→}
    67→
    68→/// Create a preference manager with a temp file path.
    69→fn make_temp_manager() -> (ProtocolPreferenceManager, TempDir) {
    70→    let temp_dir = TempDir::new().unwrap();
    71→    let path = temp_dir.path().join("protocol_preferences.json");
    72→    let mut manager = ProtocolPreferenceManager::with_path(path);
    73→    manager.set_auto_save(false);
    74→    (manager, temp_dir)
    75→}
