    78→// ProtocolPreference tests
    79→// ============================================================================
    80→
    81→#[test]
    82→fn test_protocol_preference_new() {
    83→    let pref = ProtocolPreference::new(
    84→        "binding:1234".to_string(),
    85→        "KICKR CORE 1234".to_string(),
    86→        SensorType::Trainer,
    87→        SensorProtocol::Ble,
    88→        true,
    89→    );
    90→
    91→    assert_eq!(pref.binding_id, "binding:1234");
    92→    assert_eq!(pref.sensor_name, "KICKR CORE 1234");
    93→    assert_eq!(pref.sensor_type, SensorType::Trainer);
    94→    assert_eq!(pref.preferred_protocol, SensorProtocol::Ble);
    95→    assert!(pref.user_set);
    96→    assert_eq!(pref.usage_count, 0);
    97→}
    98→
    99→#[test]
   100→fn test_protocol_preference_record_usage() {
   101→    let mut pref = ProtocolPreference::new(
   102→        "binding:1234".to_string(),
   103→        "KICKR CORE 1234".to_string(),
   104→        SensorType::Trainer,
   105→        SensorProtocol::Ble,
   106→        true,
   107→    );
   108→
   109→    assert_eq!(pref.usage_count, 0);
   110→
   111→    pref.record_usage();
   112→    assert_eq!(pref.usage_count, 1);
   113→
   114→    pref.record_usage();
   115→    assert_eq!(pref.usage_count, 2);
   116→}
   117→
   118→#[test]
   119→fn test_protocol_preference_update_protocol() {
   120→    let mut pref = ProtocolPreference::new(
   121→        "binding:1234".to_string(),
   122→        "KICKR CORE 1234".to_string(),
   123→        SensorType::Trainer,
   124→        SensorProtocol::Ble,
   125→        false,
   126→    );
   127→
   128→    assert_eq!(pref.preferred_protocol, SensorProtocol::Ble);
   129→    assert!(!pref.user_set);
   130→
   131→    pref.update_protocol(SensorProtocol::AntPlus, true);
   132→
   133→    assert_eq!(pref.preferred_protocol, SensorProtocol::AntPlus);
   134→    assert!(pref.user_set);
   135→}
