   137→// ============================================================================
   138→// DualProtocolBinding preference tests
   139→// ============================================================================
   140→
   141→#[test]
   142→fn test_binding_preferred_protocol_default() {
   143→    let sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   144→    let binding = DualProtocolBinding::new(&sensor);
   145→
   146→    assert!(binding.preferred_protocol.is_none());
   147→    assert_eq!(binding.get_effective_preferred_protocol(), SensorProtocol::Ble);
   148→}
   149→
   150→#[test]
   151→fn test_binding_set_preferred_protocol() {
   152→    let sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   153→    let mut binding = DualProtocolBinding::new(&sensor);
   154→
   155→    binding.set_preferred_protocol(SensorProtocol::AntPlus);
   156→
   157→    assert_eq!(binding.preferred_protocol, Some(SensorProtocol::AntPlus));
   158→}
   159→
   160→#[test]
   161→fn test_binding_clear_preferred_protocol() {
   162→    let sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   163→    let mut binding = DualProtocolBinding::new(&sensor);
   164→
   165→    binding.set_preferred_protocol(SensorProtocol::AntPlus);
   166→    assert!(binding.preferred_protocol.is_some());
   167→
   168→    binding.clear_preferred_protocol();
   169→    assert!(binding.preferred_protocol.is_none());
   170→}
   171→
   172→#[test]
   173→fn test_binding_get_preferred_device_id_with_preference() {
   174→    let ble_sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   175→    let ant_sensor = make_ant_sensor("KICKR CORE 1234", 1234, SensorType::Trainer);
   176→
   177→    let mut binding = DualProtocolBinding::new(&ble_sensor);
   178→    binding.add_protocol_instance(&ant_sensor);
   179→
   180→    // Without preference, should default to BLE
   181→    let default_id = binding.get_preferred_device_id();
   182→    assert_eq!(default_id, Some(ble_sensor.device_id.as_str()));
   183→
   184→    // With ANT+ preference
   185→    binding.set_preferred_protocol(SensorProtocol::AntPlus);
   186→    let preferred_id = binding.get_preferred_device_id();
   187→    assert_eq!(preferred_id, Some(ant_sensor.device_id.as_str()));
   188→
   189→    // With BLE preference
   190→    binding.set_preferred_protocol(SensorProtocol::Ble);
   191→    let preferred_id = binding.get_preferred_device_id();
   192→    assert_eq!(preferred_id, Some(ble_sensor.device_id.as_str()));
   193→}
   194→
   195→#[test]
   196→fn test_binding_preferred_protocol_fallback() {
   197→    // If preferred protocol is not available, fall back to what's available
   198→    let ble_sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   199→    let mut binding = DualProtocolBinding::new(&ble_sensor);
   200→
   201→    // Set preference to ANT+ but only BLE is available
   202→    binding.set_preferred_protocol(SensorProtocol::AntPlus);
   203→
   204→    // Should still return BLE as it's the only available option
   205→    let device_id = binding.get_preferred_device_id();
   206→    assert_eq!(device_id, Some(ble_sensor.device_id.as_str()));
   207→}
   208→
   209→#[test]
   210→fn test_binding_is_preferred_protocol_available() {
   211→    let ble_sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   212→    let mut binding = DualProtocolBinding::new(&ble_sensor);
   213→
   214→    // No preference - always available
   215→    assert!(binding.is_preferred_protocol_available());
   216→
   217→    // BLE preference - available
   218→    binding.set_preferred_protocol(SensorProtocol::Ble);
   219→    assert!(binding.is_preferred_protocol_available());
   220→
   221→    // ANT+ preference - not available (only BLE exists)
   222→    binding.set_preferred_protocol(SensorProtocol::AntPlus);
   223→    assert!(!binding.is_preferred_protocol_available());
   224→}
   225→
   226→// ============================================================================
   227→// DualProtocolDetector preference tests
   228→// ============================================================================
   229→
   230→#[test]
   231→fn test_detector_set_preferred_protocol() {
   232→    let mutdetector = DualProtocolDetector::new();
   233→
   234→    let ble_sensor = make_ble_sensor("KICKR CORE 1234", SensorType::Trainer);
   235→    let ant_sensor = make_ant_sensor("KICKR CORE 1234", 1234, SensorType::Trainer);
   236→
   237→    detector.process_sensor(&ble_sensor);
   238→    detector.process_sensor(&ant_sensor);
   239→
   240→    // Set preference via device ID
   241→    let result = detector.set_preferred_protocol(&ble_sensor.device_id, SensorProtocol::AntPlus);
   242→    assert!(result);
   243→
   244→    // Verify preference was set
   245→    let pref = detector.get_preferred_protocol(&ble_sensor.device_id);


