   229→    }
   230→
   231→    /// Enable or disable ANT+ scanning.
   232→    ///
   233→    /// When enabled, discovery will also scan for ANT+ sensors alongside BLE.
   234→    pub async fn set_ant_enabled(&self, enabled: bool) {
   235→        *self.ant_enabled.lock().await = enabled;
   236→        tracing::info!(
   237→            "ANT+ scanning {}",
   238→            if enabled { "enabled" } else { "disabled" }
   239→        );
   240→    }
   241→
   242→    /// Check if ANT+ scanning is enabled.
   243→    pub async fn is_ant_enabled(&self) -> bool {
   244→        *self.ant_enabled.lock().await
   245→    }
   246→
   247→    /// Get an event receiver for sensor events.
   248→    pub fn event_receiver(&mut self) -> Receiver<SensorEvent> {
   249→        let (tx, rx) = crossbeam::channel::unbounded();
   250→        self.event_tx = Some(tx);
   251→        rx
   252→    }
   253→
   254→    /// Send an event if the channel is available.
   255→    fn send_event(&self, event: SensorEvent) {
   256→        if let Some(tx) = &self.event_tx {
   257→            let _ = tx.send(event);
   258→        }
   259→    }
   260→
   261→    /// Start scanning for BLE and ANT+ sensors concurrently.
   262→    ///
   263→    /// When both BLE and ANT+ are enabled, both protocols scan simultaneously
   264→    /// to reduce total discovery time. This is significantly faster than
   265→    /// sequential scanning.
   266→    pub async fn start_discovery(&mut self) -> Result<(), SensorError> {
   267→        let adapter = self.adapter.as_ref().ok_or(SensorError::AdapterNotFound)?;
   268→
   269→        {
   270→            let mut is_scanning = self.is_scanning.lock().await;
   271→            if *is_scanning {
   272→                return Ok(()); // Already scanning
   273→            }
   274→            *is_scanning = true;
   275→        }
   276→
   277→        tracing::info!("Starting sensor discovery (concurrent BLE/ANT+ scanning)");
   278→
   279→        // Clear previous discoveries
   280→        self.discovered.lock().await.clear();
   281→
   282→        // Initialize power meter wake-up detection from cache
   283→        {
   284→            let cache = self.sensor_cache.lock().await;
   285→            let mut detector = self.power_meter_detector.lock().await;
   286→            detector.load_from_cache(&cache);
   287→            detector.start_discovery();
   288→        }
   289→
   290→        // Check if ANT+ should be enabled for concurrent scanning
   291→        let ant_enabled = *self.ant_enabled.lock().await;
   292→
   293→        // Run BLE and ANT+ discovery concurrently using tokio::join!
   294→        // This reduces total discovery time compared to sequential scanning
   295→        let ble_result = self.start_ble_discovery(adapter.clone()).await;
   296→
   297→        if ant_enabled {
   298→            // Start ANT+ discovery concurrently with BLE event processing
